	wgcfLinuxAmd64URL      = "https://github.com/ViRb3/wgcf/releases/download/v" + wgcfVersion + "/wgcf_" + wgcfVersion + "_linux_amd64"
	wgcfLatestReleaseAPI   = "https://api.github.com/repos/ViRb3/wgcf/releases/latest"
