// exitScript fills the n-th WDTT Plus script's interpolations in their order.
func exitScript(n int, args ...string) string {
	text := exitRaw[n]
	for i, value := range args {
		text = strings.ReplaceAll(text, fmt.Sprintf("⟦%d⟧", i), value)
	}
	return text
}

func ktIsBlank(s string) bool { return strings.TrimFunc(s, unicode.IsSpace) == "" }

// ktLines is Kotlin's String.lines(): \r\n, \n and \r all end a line.
func ktLines(s string) []string {
	return strings.Split(strings.ReplaceAll(strings.ReplaceAll(s, "\r\n", "\n"), "\r", "\n"), "\n")
}

// trimIndent is Kotlin's String.trimIndent(): the common indent of non-blank lines goes,
// and a blank first or last line is dropped.
func trimIndent(s string) string {
	lines := ktLines(s)
	minIndent := -1
	for _, line := range lines {
		if ktIsBlank(line) {
			continue
		}
		width := len([]rune(line))
		for i, r := range []rune(line) {
			if !unicode.IsSpace(r) {
				width = i
				break
			}
		}
		if minIndent < 0 || width < minIndent {
			minIndent = width
		}
	}
	if minIndent < 0 {
		minIndent = 0
	}
	out := make([]string, 0, len(lines))
	for i, line := range lines {
		if (i == 0 || i == len(lines)-1) && ktIsBlank(line) {
			continue
		}
		runes := []rune(line)
		if len(runes) >= minIndent {
			out = append(out, string(runes[minIndent:]))
		} else {
			out = append(out, "")
		}
	}
	return strings.Join(out, "\n")
}

// shellScript joins blocks as WDTT Plus does: each trimIndent()ed and stripped of newlines.
func shellScript(blocks ...string) string {
	parts := make([]string, len(blocks))
	for i, block := range blocks {
		parts[i] = strings.Trim(trimIndent(block), "\n")
	}
	return strings.TrimFunc(strings.Join(parts, "\n"), unicode.IsSpace) + "\n"
}

func exitRootCommand(command string) string {
	quoted := quote(command)
	return `if [ "$(id -u)" = "0" ]; then bash -c ` + quoted + "; " +
		"elif command -v sudo >/dev/null 2>&1; then sudo -S -p '' bash -c " + quoted + "; " +
		"else echo 'error: root privileges required and sudo not found'; exit 1; fi"
}

func randomToken(length int) string {
	const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789"
	var b strings.Builder
	for i := 0; i < length; i++ {
		n, _ := rand.Int(rand.Reader, big.NewInt(int64(len(alphabet))))
		b.WriteByte(alphabet[n.Int64()])
	}
	return b.String()
}

func markerValue(output, name string) (string, bool) {
	m := regexp.MustCompile(`(?m)^` + regexp.QuoteMeta(name) + `=(.*)$`).FindStringSubmatch(output)
	if m == nil {
		return "", false
	}
	return strings.TrimFunc(m[1], unicode.IsSpace), true
}

func b64Text(value string) string { return base64.StdEncoding.EncodeToString([]byte(value)) }

func decodeB64Text(value string) string {
	raw, err := base64.StdEncoding.DecodeString(value)
	if err != nil {
		return ""
	}
	return string(raw)
}

func takeRunes(s string, n int) string {
	r := []rune(s)
	if len(r) > n {
		return string(r[:n])
	}
	return s
}

func takeLastRunes(s string, n int) string {
	r := []rune(s)
	if len(r) > n {
		return string(r[len(r)-n:])
	}
	return s
}

// rootScriptErrorExcerpt keeps the error marker and its details even after a long log.
func rootScriptErrorExcerpt(output string) string {
	all := regexp.MustCompile(`(?m)^WDTT_ERROR=`).FindAllStringIndex(output, -1)
	if len(all) > 0 {
		return takeRunes(output[all[len(all)-1][0]:], 1600)
	}
	return takeLastRunes(output, 1600)
}

// friendlyDeployError is the last non-blank line of a failure, at most 300 characters.
func friendlyDeployError(message, operation string) string {
	lines := ktLines(message)
	for i := len(lines) - 1; i >= 0; i-- {
		if line := strings.TrimFunc(lines[i], unicode.IsSpace); line != "" {
			return takeRunes(line, 300)
		}
	}
	return "операция «" + operation + "» завершилась с неизвестной ошибкой"
}

var (
	localLoginPattern    = regexp.MustCompile(`^[A-Za-z0-9._@+-]{1,40}$`)
	localPasswordPattern = regexp.MustCompile(`^[A-Za-z0-9._~!@%+?,=-]{8,80}$`)
	tunNamePattern       = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9_.:-]*$`)
	ipv4Pattern          = regexp.MustCompile(`^(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}$`)
)

func localProxyCredentialsIssue(login, password string) string {
	switch {
	case ktIsBlank(login):
		return "Укажите логин прокси."
	case !localLoginPattern.MatchString(login):
		return "В логине допустимы латинские буквы, цифры и знаки . _ @ + -"
	case len([]rune(password)) < 8 || len([]rune(password)) > 80:
		return "Пароль должен содержать от 8 до 80 символов."
	case !localPasswordPattern.MatchString(password):
		return "В пароле допустимы латинские буквы, цифры и знаки . _ ~ ! @ % + ? , = -"
	}
	return ""
}

func hasControl(s string) bool {
	for _, r := range s {
		if unicode.IsControl(r) {
			return true
		}
	}
	return false
}

func externalProxyCredentialsIssue(login, password string) string {
	switch {
	case ktIsBlank(login) && !ktIsBlank(password):
		return "Для пароля внешнего прокси укажите логин."
	case !ktIsBlank(login) && ktIsBlank(password):
		return "Для указанного логина внешнего прокси введите пароль."
	case len([]rune(login)) > 80:
		return "Логин внешнего прокси не должен быть длиннее 80 символов."
	case len([]rune(password)) > 120:
		return "Пароль внешнего прокси не должен быть длиннее 120 символов."
	case strings.Contains(login, ":"):
		return "Логин внешнего прокси не должен содержать двоеточие."
	case hasControl(login) || hasControl(password):
		return "Логин и пароль внешнего прокси содержат недопустимые символы."
	}
	return ""
}

func tunInterfaceNameIssue(value string) string {
	name := strings.TrimFunc(value, unicode.IsSpace)
	switch {
	case name == "":
		return "Укажите имя TUN-интерфейса."
	case len([]rune(name)) > 15:
		return "Имя сетевого интерфейса не должно быть длиннее 15 символов."
	case !tunNamePattern.MatchString(name):
		return "Имя интерфейса должно начинаться с латинской буквы или цифры; далее допустимы знаки . _ : -"
	case name == "lo" || name == "wdtt0" || name == "wg-wdtt-exit":
		return "Интерфейс " + name + " зарезервирован и не может быть выбран как внешний TUN."
	}
	return ""
}

func escapeRedsocksQuotedValue(value string) string {
	return strings.ReplaceAll(strings.ReplaceAll(value, `\`, `\\`), `"`, `\"`)
}

func isValidPublicHost(raw string) bool {
	value := strings.TrimFunc(raw, unicode.IsSpace)
	if value == "" || len([]rune(value)) > 253 || strings.ContainsAny(value, `/\:@`) {
		return false
	}
	if ipv4Pattern.MatchString(value) {
		return true
	}
	if strings.HasPrefix(value, ".") || strings.HasSuffix(value, ".") || strings.Contains(value, "..") {
		return false
	}
	labels := strings.Split(value, ".")
	if len(labels) < 2 {
		return false
	}
	for _, label := range labels {
		if ktIsBlank(label) || len([]rune(label)) > 63 || strings.HasPrefix(label, "-") || strings.HasSuffix(label, "-") {
			return false
		}
		for _, r := range label {
			if !unicode.IsLetter(r) && !unicode.IsDigit(r) && r != '-' {
				return false
			}
		}
	}
	return true
}

// The scripts, as WDTT Plus composes them.

func outboundProbeFunctions() string      { return trimIndent(exitScript(3)) }
func externalProxyProbeFunctions() string { return trimIndent(exitScript(4)) }
func indentLines(s, indent string) string { return strings.ReplaceAll(s, "\n", "\n"+indent) }

func outboundShellPrelude() string {
	return trimIndent(exitScript(5, indentLines(outboundProbeFunctions(), "    "), indentLines(externalProxyProbeFunctions(), "    ")))
}
func outboundReadPrelude() string          { return trimIndent(exitScript(6)) }
func outboundStatusScript() string         { return shellScript(outboundShellPrelude(), exitScript(7)) }
func tunInterfaceCandidatesScript() string { return trimIndent(exitScript(8)) }
func outboundSnapshotScript() string       { return shellScript(outboundReadPrelude(), exitScript(11)) }
func disableOutboundExitScript() string    { return shellScript(outboundShellPrelude(), exitScript(14)) }
func deleteTunInterfaceExitScript() string {
	return shellScript(outboundShellPrelude(), exitScript(17))
}
func stopLocalProxyScript() string      { return trimIndent(exitScript(21)) }
func removeLocalProxyScript() string    { return shellScript(outboundShellPrelude(), exitScript(22)) }
func externalProxyRoutesScript() string { return trimIndent(exitScript(24)) + "\n" }
func deleteExternalProxyScript() string { return shellScript(outboundShellPrelude(), exitScript(26)) }
func freeWarpAutoTuneScript() string    { return trimIndent(exitScript(30)) }
func deleteImportedWireGuardScript() string {
	return shellScript(outboundShellPrelude(), exitScript(39))
}
func deleteVpsCurrentScript() string { return shellScript(outboundShellPrelude(), exitScript(40)) }
func deleteVpsForeignScript() string { return trimIndent(exitScript(41)) }

func wgcfToolManagementScript() string {
	return trimIndent(exitScript(28, quote(wgcfVersion), quote(wgcfLinuxAmd64URL), quote(wgcfLinuxAmd64SHA256), quote(wgcfLatestReleaseAPI)))
}

func freeWarpWatchdogInstallScript() string {
	return trimIndent(exitScript(29, indentLines(outboundProbeFunctions(), "    ")))
}

func wireGuardPolicyScript(mode, detail string) string {
	q := quote(mode)
	return shellScript(outboundShellPrelude(), exitScript(27, q, q, q, q, quote(detail)))
}

func buildTunInterfaceExitScript(name string) (string, error) {
	if issue := tunInterfaceNameIssue(name); issue != "" {
		return "", errors.New(issue)
	}
	q := quote(strings.TrimFunc(name, unicode.IsSpace))
	return shellScript(outboundShellPrelude(), exitScript(15, q, q)), nil
}

func checkTunInterfaceExitScript(name string) (string, error) {
	if issue := tunInterfaceNameIssue(name); issue != "" {
		return "", errors.New(issue)
	}
	return shellScript(outboundShellPrelude(), exitScript(16, quote(strings.TrimFunc(name, unicode.IsSpace)))), nil
}

func localProxyFirewallScript(port int) (string, error) {
	if port < 1 || port > 65533 {
		return "", errors.New("порт SOCKS5 должен быть от 1 до 65533")
	}
	return trimIndent(exitScript(18, strconv.Itoa(port), strconv.Itoa(port+1), strconv.Itoa(port+2))) + "\n", nil
}

func buildLocalProxyInstallScript(port int, login, password string) (string, error) {
	if port < 1 || port > 65533 {
		return "", errors.New("порт SOCKS5 должен быть от 1 до 65533")
	}
	if issue := localProxyCredentialsIssue(login, password); issue != "" {
		return "", errors.New(issue)
	}
	httpPort := min(port+1, 65535)
	firewall, _ := localProxyFirewallScript(port)
	return shellScript(outboundShellPrelude(), exitScript(19, strconv.Itoa(port), strconv.Itoa(httpPort), strconv.Itoa(httpPort+1),
		quote(login), quote(password), quote(threeProxyVersion), quote(threeProxySourceURL), quote(threeProxySourceSHA256),
		quote(b64Text(firewall)), indentLines(outboundProbeFunctions(), "        "))), nil
}

func checkLocalProxyScript(port int, login, password string) (string, error) {
	if port < 1 || port > 65533 {
		return "", errors.New("порт SOCKS5 должен быть от 1 до 65533")
	}
	if issue := localProxyCredentialsIssue(login, password); issue != "" {
		return "", errors.New(issue)
	}
	return trimIndent(exitScript(20, strconv.Itoa(port), quote(login), quote(password), indentLines(outboundProbeFunctions(), "        "))), nil
}

type proxyKind struct{ name, label, protocol string }

var proxyKinds = []proxyKind{{"Socks5", "SOCKS5", "socks5"}, {"Http", "HTTP", "http"}}

func proxyKindByName(name string) (proxyKind, bool) {
	for _, kind := range proxyKinds {
		if kind.name == name {
			return kind, true
		}
	}
	return proxyKind{}, false
}

func checkExternalProxyCheck(kind proxyKind, host string, port int, login, password string) error {
	if !isValidPublicHost(host) {
		return errors.New("укажите домен или IPv4 внешнего прокси без схемы и порта")
	}
	if port < 1 || port > 65535 {
		return errors.New("порт внешнего прокси должен быть от 1 до 65535")
	}
	if issue := externalProxyCredentialsIssue(login, password); issue != "" {
		return errors.New(issue)
	}
	return nil
}

func checkExternalProxyScript(kind proxyKind, host string, port int, login, password string) (string, error) {
	if err := checkExternalProxyCheck(kind, host, port, login, password); err != nil {
		return "", err
	}
	scheme := "http"
	if kind.name == "Socks5" {
		scheme = "socks5h"
	}
	probe := indentLines(outboundProbeFunctions(), "        ")
	return shellScript(externalProxyProbeFunctions(), trimIndent(exitScript(23, kind.label, quote(scheme+"://"+host+":"+strconv.Itoa(port)),
		quote(login), quote(password), probe, probe, kind.label))), nil
}

func enableExternalProxyScript(kind proxyKind, host string, port int, login, password string) (string, error) {
	if err := checkExternalProxyCheck(kind, host, port, login, password); err != nil {
		return "", err
	}
	redsocksType := "http-connect"
	if kind.name == "Socks5" {
		redsocksType = "socks5"
	}
	return shellScript(outboundShellPrelude(), exitScript(25, quote(kind.protocol), quote(redsocksType), quote(host), strconv.Itoa(port),
		quote(login), quote(password), quote(escapeRedsocksQuotedValue(login)), quote(escapeRedsocksQuotedValue(password)),
		quote(b64Text(externalProxyRoutesScript())))), nil
}

func buildFreeWarpInstallScript(mtu int) (string, error) {
	if mtu < 1280 || mtu > 1500 {
		return "", errors.New("MTU WARP должен быть от 1280 до 1500")
	}
	return shellScript("WARP_MTU="+strconv.Itoa(mtu), outboundShellPrelude(), wgcfToolManagementScript(), exitScript(32),
		freeWarpAutoTuneScript(), wireGuardPolicyScript("warp_free", "бесплатный Cloudflare WARP"), freeWarpWatchdogInstallScript(), exitScript(33)), nil
}

func checkFreeWarpScript(restart bool) string {
	flag := "0"
	if restart {
		flag = "1"
	}
	return shellScript(outboundShellPrelude(), exitScript(34), freeWarpAutoTuneScript(), exitScript(35, flag))
}

func checkWireGuardExitScript(expectedMode string) string {
	label := expectedMode
	switch expectedMode {
	case "wireguard_vps":
		label = "выход через другой сервер"
	case "warp_free":
		label = "бесплатный WARP"
	case "imported_wg":
		label = "VPN/WireGuard-файл"
	}
	return shellScript(outboundShellPrelude(), exitScript(12, quote(expectedMode), label))
}

// outboundProfileForms are the fields WDTT Plus keeps on the server to restore its screen.
type outboundProfileForms struct {
	LocalProxyPort          string `json:"localProxyPort"`
	LocalProxyLogin         string `json:"localProxyLogin"`
	LocalProxyPassword      string `json:"localProxyPassword"`
	ExternalProxyKindName   string `json:"externalProxyKindName"`
	ExternalProxyHost       string `json:"externalProxyHost"`
	ExternalProxyPort       string `json:"externalProxyPort"`
	ExternalProxyLogin      string `json:"externalProxyLogin"`
	ExternalProxyPassword   string `json:"externalProxyPassword"`
	WireGuardExitHost       string `json:"wireGuardExitHost"`
	WireGuardExitSSHPort    string `json:"wireGuardExitSshPort"`
	WireGuardExitUser       string `json:"wireGuardExitUser"`
	WireGuardExitPort       string `json:"wireGuardExitPort"`
	WireGuardExitDNS        string `json:"wireGuardExitDns"`
	ImportedWireGuardConfig string `json:"importedWireGuardConfig"`
	TunInterface            string `json:"tunInterface"`
}

func digitsPort(value string) string {
	var b strings.Builder
	for _, r := range value {
		if r >= '0' && r <= '9' && b.Len() < 5 {
			b.WriteRune(r)
		}
	}
	return b.String()
}

func outboundProfileSaveScript(f outboundProfileForms) string {
	kind := ""
	if k, ok := proxyKindByName(f.ExternalProxyKindName); ok {
		kind = k.name
	}
	lines := []string{
		"VERSION=1",
		"LOCAL_PROXY_PORT=" + digitsPort(f.LocalProxyPort),
		"LOCAL_PROXY_LOGIN_B64=" + b64Text(f.LocalProxyLogin),
		"LOCAL_PROXY_PASSWORD_B64=" + b64Text(f.LocalProxyPassword),
		"EXTERNAL_PROXY_KIND=" + kind,
		"EXTERNAL_PROXY_HOST_B64=" + b64Text(f.ExternalProxyHost),
		"EXTERNAL_PROXY_PORT=" + digitsPort(f.ExternalProxyPort),
		"EXTERNAL_PROXY_LOGIN_B64=" + b64Text(f.ExternalProxyLogin),
		"EXTERNAL_PROXY_PASSWORD_B64=" + b64Text(f.ExternalProxyPassword),
		"WG_VPS_HOST_B64=" + b64Text(f.WireGuardExitHost),
		"WG_VPS_SSH_PORT=" + digitsPort(f.WireGuardExitSSHPort),
		"WG_VPS_USER_B64=" + b64Text(f.WireGuardExitUser),
		// The second VPS's SSH password is needed only while setting it up: no root access to it stays on this server.
		"WG_VPS_PASSWORD_B64=" + b64Text(""),
		"WG_VPS_PORT=" + digitsPort(f.WireGuardExitPort),
		// Client DNS is set in the main WDTT settings, not in the policy-routed WireGuard exit.
		"WG_VPS_DNS_B64=" + b64Text(""),
		"IMPORTED_WG_CONFIG_B64=" + b64Text(f.ImportedWireGuardConfig),
		"TUN_INTERFACE_B64=" + b64Text(f.TunInterface),
	}
	profile := trimIndent(exitScript(9)) + "\n" + strings.Join(lines, "\n") + "\n" + trimIndent(exitScript(10))
	return shellScript(outboundShellPrelude(), profile)
}

var wgSectionPattern = map[string]*regexp.Regexp{
	"interface": regexp.MustCompile(`(?im)^\s*\[Interface]\s*$`), "privatekey": regexp.MustCompile(`(?im)^\s*PrivateKey\s*=\s*\S+`),
	"address": regexp.MustCompile(`(?im)^\s*Address\s*=\s*\S+`), "peer": regexp.MustCompile(`(?im)^\s*\[Peer]\s*$`),
	"publickey": regexp.MustCompile(`(?im)^\s*PublicKey\s*=\s*\S+`), "endpoint": regexp.MustCompile(`(?im)^\s*Endpoint\s*=\s*\S+`),
	"allowedips": regexp.MustCompile(`(?im)^\s*AllowedIPs\s*=\s*\S+`), "hooks": regexp.MustCompile(`(?im)^\s*(PreUp|PostUp|PreDown|PostDown)\s*=`),
	"allowedvalue": regexp.MustCompile(`(?im)^\s*AllowedIPs\s*=\s*(.+)$`),
}

// validateWireGuardConfigText is WDTT Plus's check of an uploaded WireGuard file.
func validateWireGuardConfigText(config string) error {
	raw := strings.TrimFunc(config, unicode.IsSpace)
	checks := []struct {
		ok      bool
		message string
	}{
		{len(raw) <= 64*1024, "файл больше 64 КБ"},
		{!strings.ContainsRune(raw, 0), "файл содержит недопустимые нулевые байты"},
		{wgSectionPattern["interface"].MatchString(raw), "не найден раздел с настройками вашего WireGuard-клиента"},
		{wgSectionPattern["privatekey"].MatchString(raw), "в файле нет приватного ключа клиента"},
		{wgSectionPattern["address"].MatchString(raw), "в файле нет адреса клиента"},
		{wgSectionPattern["peer"].MatchString(raw), "не найден раздел с настройками удалённого сервера"},
		{wgSectionPattern["publickey"].MatchString(raw), "в файле нет публичного ключа удалённого сервера"},
		{wgSectionPattern["endpoint"].MatchString(raw), "в файле нет адреса удалённого сервера"},
		{wgSectionPattern["allowedips"].MatchString(raw), "в файле нет маршрутов для WireGuard"},
		{!wgSectionPattern["hooks"].MatchString(raw), "команды запуска и остановки запрещены для безопасного импорта"},
	}
	for _, check := range checks {
		if !check.ok {
			return errors.New(check.message)
		}
	}
	interfaceKeys := map[string]bool{"privatekey": true, "address": true, "dns": true, "mtu": true, "table": true, "listenport": true}
	peerKeys := map[string]bool{"publickey": true, "presharedkey": true, "allowedips": true, "endpoint": true, "persistentkeepalive": true}
	section, interfaces, peers := "", 0, 0
	for index, source := range ktLines(raw) {
		line := strings.TrimFunc(source, unicode.IsSpace)
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			section = strings.ToLower(strings.TrimFunc(line[1:len(line)-1], unicode.IsSpace))
			switch section {
			case "interface":
				interfaces++
			case "peer":
				peers++
			default:
				return fmt.Errorf("неподдерживаемый раздел в строке %d", index+1)
			}
			continue
		}
		separator := strings.Index(line, "=")
		if separator < 1 || separator >= len(line)-1 {
			return fmt.Errorf("неверная строка %d", index+1)
		}
		key := strings.ToLower(strings.TrimFunc(line[:separator], unicode.IsSpace))
		value := strings.TrimFunc(line[separator+1:], unicode.IsSpace)
		if value == "" {
			return fmt.Errorf("пустое значение в строке %d", index+1)
		}
		allowed := map[string]bool{}
		if section == "interface" {
			allowed = interfaceKeys
		} else if section == "peer" {
			allowed = peerKeys
		}
		if !allowed[key] {
			return fmt.Errorf("параметр %s не разрешён для безопасного импорта", strings.TrimFunc(line[:separator], unicode.IsSpace))
		}
		if key == "mtu" {
			mtu, err := strconv.Atoi(value)
			if err != nil || mtu < 576 || mtu > 9000 {
				return errors.New("MTU должен быть от 576 до 9000")
			}
		}
		if key == "endpoint" {
			at := strings.LastIndex(value, ":")
			port, err := strconv.Atoi(value[at+1:])
			if at < 0 || err != nil || port < 1 || port > 65535 || strings.IndexFunc(value, unicode.IsSpace) >= 0 {
				return errors.New("Endpoint должен содержать адрес и порт от 1 до 65535")
			}
		}
	}
	if interfaces != 1 {
		return errors.New("должен быть ровно один раздел [Interface]")
	}
	if peers != 1 {
		return errors.New("должен быть ровно один раздел [Peer]")
	}
	allowedIPs := ""
	if m := wgSectionPattern["allowedvalue"].FindStringSubmatch(raw); m != nil {
		allowedIPs = m[1]
	}
	for _, item := range strings.Split(allowedIPs, ",") {
		if strings.TrimFunc(item, unicode.IsSpace) == "0.0.0.0/0" {
			return nil
		}
	}
	return errors.New("для выходного VPN в AllowedIPs должен быть маршрут 0.0.0.0/0")
}

// sanitizeWireGuardConfigForWdttExit sets Table = off and drops DNS and hook lines.
func sanitizeWireGuardConfigForWdttExit(config string) (string, error) {
	if err := validateWireGuardConfigText(config); err != nil {
		return "", err
	}
	var out []string
	inInterface, tableInserted := false, false
	hasPrefixFold := func(s, prefix string) bool {
		return len(s) >= len(prefix) && strings.EqualFold(s[:len(prefix)], prefix)
	}
	for _, line := range ktLines(strings.TrimFunc(config, unicode.IsSpace)) {
		trimmed := strings.TrimFunc(line, unicode.IsSpace)
		if strings.EqualFold(trimmed, "[Interface]") {
			inInterface, tableInserted = true, false
			out = append(out, "[Interface]")
			continue
		}
		if strings.HasPrefix(trimmed, "[") && strings.HasSuffix(trimmed, "]") {
			if inInterface && !tableInserted {
				out = append(out, "Table = off")
				tableInserted = true
			}
			inInterface = false
			out = append(out, trimmed)
			continue
		}
		if hasPrefixFold(trimmed, "Table") || hasPrefixFold(trimmed, "DNS") || hasPrefixFold(trimmed, "PreUp") || hasPrefixFold(trimmed, "PostUp") ||
			hasPrefixFold(trimmed, "PreDown") || hasPrefixFold(trimmed, "PostDown") {
			continue
		}
		out = append(out, line)
	}
	if inInterface && !tableInserted {
		out = append(out, "Table = off")
	}
	return strings.TrimFunc(strings.Join(out, "\n"), unicode.IsSpace) + "\n", nil
}

// outboundSnapshot is the server's exit state as the snapshot script reports it.
type outboundSnapshot map[string]any

func parseOutboundServerSnapshot(output string) outboundSnapshot {
	value := func(name string) string { v, _ := markerValue(output, name); return v }
	decoded := func(name string) string {
		if raw := value(name); !ktIsBlank(raw) {
			return decodeB64Text(raw)
		}
		return ""
	}
	flag := func(name string) bool { return value(name) == "1" }
	mode := value("WDTT_OUTBOUND_MODE")
	if ktIsBlank(mode) {
		mode = "direct"
	}
	kind := value("WDTT_EXTERNAL_PROXY_KIND_NAME")
	if _, ok := proxyKindByName(kind); !ok {
		kind = ""
	}
	s := outboundSnapshot{
		"mode": mode, "detail": decoded("WDTT_OUTBOUND_DETAIL_B64"), "updatedAt": value("WDTT_OUTBOUND_UPDATED_AT"),
		"hasProfile": flag("WDTT_HAS_PROFILE"), "localProxyPresent": flag("WDTT_LOCAL_PROXY_PRESENT"), "localProxyActive": flag("WDTT_LOCAL_PROXY_ACTIVE"),
		"localProxyPort": value("WDTT_LOCAL_PROXY_PORT"), "localProxyLogin": decoded("WDTT_LOCAL_PROXY_LOGIN_B64"),
		"localProxyPassword": decoded("WDTT_LOCAL_PROXY_PASSWORD_B64"), "externalProxyPresent": flag("WDTT_EXTERNAL_PROXY_PRESENT"),
		"externalProxyActive": flag("WDTT_EXTERNAL_PROXY_ACTIVE"), "externalProxyKindName": kind,
		"externalProxyHost": decoded("WDTT_EXTERNAL_PROXY_HOST_B64"), "externalProxyPort": value("WDTT_EXTERNAL_PROXY_PORT"),
		"externalProxyLogin": decoded("WDTT_EXTERNAL_PROXY_LOGIN_B64"), "externalProxyPassword": decoded("WDTT_EXTERNAL_PROXY_PASSWORD_B64"),
		"externalProxyProfileSaved": flag("WDTT_EXTERNAL_PROXY_PROFILE_SAVED"), "wireGuardPresent": flag("WDTT_WG_PRESENT"),
		"wireGuardActive": flag("WDTT_WG_ACTIVE"), "wireGuardExitHost": decoded("WDTT_WG_VPS_HOST_B64"),
		"wireGuardExitSshPort": value("WDTT_WG_VPS_SSH_PORT"), "wireGuardExitUser": decoded("WDTT_WG_VPS_USER_B64"),
		"wireGuardExitPassword": decoded("WDTT_WG_VPS_PASSWORD_B64"), "wireGuardExitPort": value("WDTT_WG_VPS_PORT"),
		"wireGuardExitDns": decoded("WDTT_WG_VPS_DNS_B64"), "warpPresent": flag("WDTT_WARP_PRESENT"), "warpMtu": value("WDTT_WARP_MTU"),
		"importedWireGuardConfig":    decoded("WDTT_IMPORTED_WG_CONFIG_B64"),
		"externalProxyServiceActive": flag("WDTT_EXTERNAL_PROXY_SERVICE_ACTIVE"), "externalProxyRouteActive": flag("WDTT_EXTERNAL_PROXY_ROUTE_ACTIVE"),
		"wireGuardInterfaceActive": flag("WDTT_WG_INTERFACE_ACTIVE"), "wireGuardServiceActive": flag("WDTT_WG_SERVICE_ACTIVE"),
		"wireGuardPolicyRuleActive": flag("WDTT_WG_POLICY_RULE_ACTIVE"), "wireGuardDefaultRouteActive": flag("WDTT_WG_DEFAULT_ROUTE_ACTIVE"),
		"wireGuardNatActive": flag("WDTT_WG_NAT_ACTIVE"), "wireGuardOwnerMode": value("WDTT_WG_OWNER_MODE"),
		"wireGuardConfigOwnerMode": value("WDTT_WG_CONFIG_OWNER_MODE"), "wireGuardMatchesWarp": flag("WDTT_WG_MATCHES_WARP"),
		"localProxyServiceEnabled": flag("WDTT_LOCAL_PROXY_SERVICE_ENABLED"), "externalProxyServiceEnabled": flag("WDTT_EXTERNAL_PROXY_SERVICE_ENABLED"),
		"wireGuardServiceEnabled": flag("WDTT_WG_SERVICE_ENABLED"), "tunInterface": decoded("WDTT_TUN_INTERFACE_B64"),
		"tunProfileSaved": flag("WDTT_TUN_PROFILE_SAVED"), "tunPresent": flag("WDTT_TUN_PRESENT"), "tunInterfaceActive": flag("WDTT_TUN_INTERFACE_ACTIVE"),
		"tunServiceActive": flag("WDTT_TUN_SERVICE_ACTIVE"), "tunServiceEnabled": flag("WDTT_TUN_SERVICE_ENABLED"),
		"tunPolicyRuleActive": flag("WDTT_TUN_POLICY_RULE_ACTIVE"), "tunDefaultRouteActive": flag("WDTT_TUN_DEFAULT_ROUTE_ACTIVE"),
		"tunForwardRulesActive": flag("WDTT_TUN_FORWARD_RULES_ACTIVE"), "tunIpForwardActive": flag("WDTT_TUN_IP_FORWARD_ACTIVE"),
		"tunFailClosedActive": flag("WDTT_TUN_FAIL_CLOSED_ACTIVE"),
	}
	s["modeLabel"] = s.modeLabel()
	if message := s.routeConflictMessage(); message != "" {
		s["routeConflict"] = message
	}
	return s
}

func (s outboundSnapshot) b(key string) bool   { v, _ := s[key].(bool); return v }
func (s outboundSnapshot) t(key string) string { v, _ := s[key].(string); return v }

func (s outboundSnapshot) modeLabel() string {
	switch s.t("mode") {
	case "direct":
		return "прямой выход"
	case "external_proxy":
		return "внешний TCP-прокси"
	case "tun_interface":
		return "существующий TUN-интерфейс"
	case "warp_free":
		return "бесплатный WARP"
	case "imported_wg":
		return "VPN/WireGuard-файл"
	case "wireguard_vps":
		return "выход через другой сервер"
	case "":
		return "не указан"
	}
	return s.t("mode")
}

func (s outboundSnapshot) externalProxyRoutingPresent() bool {
	return s.b("externalProxyServiceActive") || s.b("externalProxyRouteActive")
}
func (s outboundSnapshot) wireGuardRoutingPresent() bool {
	return s.b("wireGuardInterfaceActive") || s.b("wireGuardPolicyRuleActive") || s.b("wireGuardDefaultRouteActive") || s.b("wireGuardNatActive")
}
func (s outboundSnapshot) tunRoutingPresent() bool {
	return s.b("tunServiceActive") || s.b("tunPolicyRuleActive") || s.b("tunDefaultRouteActive") || s.b("tunForwardRulesActive")
}
func (s outboundSnapshot) tunHealthy() bool {
	return s.b("tunPresent") && s.b("tunInterfaceActive") && s.b("tunServiceActive") && s.b("tunServiceEnabled") &&
		s.b("tunPolicyRuleActive") && s.b("tunDefaultRouteActive") && s.b("tunForwardRulesActive") && s.b("tunIpForwardActive")
}

func (s outboundSnapshot) routeConflictMessage() string {
	var labels []string
	if s.b("externalProxyRouteActive") {
		labels = append(labels, "внешний TCP-прокси")
	}
	if s.wireGuardRoutingPresent() {
		labels = append(labels, "WireGuard-выход")
	}
	if s.tunRoutingPresent() {
		labels = append(labels, "TUN-интерфейс")
	}
	if len(labels) < 2 {
		return ""
	}
	return "На сервере одновременно остались несколько маршрутов внешнего выхода WDTT: " + strings.Join(labels, " и ") +
		". Это может нарушить интернет у клиентов; нажмите «Вернуть прямой выход», затем включите только один режим."
}

func (s outboundSnapshot) summary() string {
	parts := []string{"Поля выходного IP прочитаны с сервера.", "Активный режим: " + s.modeLabel() + "."}
	if s.b("hasProfile") {
		parts = append(parts, "Сохранённый профиль найден.")
	}
	if s.b("localProxyPresent") {
		if s.b("localProxyActive") {
			parts = append(parts, "Прокси на этом VPS найден и запущен.")
		} else {
			parts = append(parts, "Прокси на этом VPS найден, служба не запущена.")
		}
	}
	if s.b("externalProxyPresent") {
		if s.b("externalProxyActive") {
			parts = append(parts, "Внешний TCP-прокси включён.")
		} else {
			parts = append(parts, "Поля внешнего TCP-прокси заполнены.")
		}
	} else if s.b("externalProxyProfileSaved") {
		parts = append(parts, "Сохранены только поля внешнего TCP-прокси; служба и маршрутизация WDTT не настроены.")
	}
	if s.b("wireGuardPresent") {
		if s.b("wireGuardActive") {
			parts = append(parts, "WireGuard-выход найден и запущен.")
		} else {
			parts = append(parts, "Поля WireGuard-выхода заполнены.")
		}
	}
	if s.b("tunPresent") {
		if s.tunHealthy() {
			parts = append(parts, "Выход через TUN-интерфейс "+s.t("tunInterface")+" найден и запущен.")
		} else {
			name := s.t("tunInterface")
			if ktIsBlank(name) {
				name = "без имени"
			}
			parts = append(parts, "Настройка TUN-интерфейса "+name+" найдена, но маршрут сейчас не активен.")
		}
	} else if s.b("tunProfileSaved") {
		parts = append(parts, "Сохранено только имя TUN-интерфейса для повторного включения; маршрутизация WDTT через него не настроена.")
	}
	if s.t("mode") == "warp_free" {
		if s.b("wireGuardActive") {
			parts = append(parts, "Бесплатный WARP найден; откройте его окно для проверки Cloudflare и автопроверки.")
		} else {
			parts = append(parts, "Профиль бесплатного WARP найден, но WireGuard сейчас не запущен. Нажмите «Установить / восстановить».")
		}
	}
	if s.b("localProxyPresent") && ktIsBlank(s.t("localProxyPassword")) {
		parts = append(parts, "Пароль прокси не найден в старом серверном конфиге; введите его вручную.")
	}
	if s.t("mode") == "wireguard_vps" && ktIsBlank(s.t("wireGuardExitPassword")) {
		parts = append(parts, "SSH-пароль второго сервера в сохранённом профиле не найден; введите пароль или локально добавьте приватный SSH-ключ.")
	}
	return strings.Join(parts, " ")
}

var wireGuardOutboundModes = map[string]bool{"wireguard_vps": true, "warp_free": true, "imported_wg": true}

// warning is WDTT Plus's check that the written mode is the one actually running.
func (s outboundSnapshot) warning() string {
	mode := s.t("mode")
	switch {
	case s.routeConflictMessage() != "":
		return s.routeConflictMessage()
	case mode == "direct" && (s.externalProxyRoutingPresent() || s.wireGuardRoutingPresent() || s.tunRoutingPresent()):
		return "записан прямой выход, но на сервере остались внешние службы или правила маршрутизации. Нажмите «Вернуть прямой выход» для полной очистки."
	case mode == "external_proxy" && s.b("externalProxyServiceActive") && !s.b("externalProxyRouteActive"):
		return "служба внешнего TCP-прокси запущена, но правило перенаправления трафика WDTT отсутствует."
	case mode == "external_proxy" && !s.b("externalProxyServiceActive") && s.b("externalProxyRouteActive"):
		return "правило внешнего TCP-прокси осталось, но его служба не запущена; TCP-трафик клиентов может не работать."
	case mode == "external_proxy" && s.b("externalProxyActive") && !s.b("externalProxyServiceEnabled"):
		return "внешний TCP-прокси работает, но его автозапуск выключен; после перезагрузки сервера режим пропадёт."
	case mode == "external_proxy" && !s.b("externalProxyActive"):
		return "режим записан как внешний TCP-прокси, но он запущен не полностью."
	case wireGuardOutboundModes[mode] && s.b("wireGuardActive") && !s.b("wireGuardServiceActive"):
		return "WireGuard-маршрут работает, но постоянная служба не активна; после перезагрузки сервера режим может пропасть."
	case wireGuardOutboundModes[mode] && s.b("wireGuardActive") && !s.b("wireGuardServiceEnabled"):
		return "WireGuard-маршрут работает, но автозапуск службы выключен; после перезагрузки сервера режим пропадёт."
	case wireGuardOutboundModes[mode] && !s.b("wireGuardActive"):
		return "режим записан как " + s.modeLabel() + ", но не все компоненты WireGuard-маршрута запущены."
	case mode == "tun_interface" && !s.tunHealthy():
		if s.b("tunFailClosedActive") {
			return "внешний TUN недоступен; аварийная блокировка защищает трафик WDTT от прямого выхода."
		}
		return "режим записан как существующий TUN-интерфейс, но интерфейс, служба или управляемые маршруты запущены не полностью."
	case s.externalProxyRoutingPresent() && mode != "external_proxy":
		return "на сервере остались компоненты внешнего TCP-прокси, хотя записан режим «" + s.modeLabel() + "»."
	case s.wireGuardRoutingPresent() && !wireGuardOutboundModes[mode]:
		return "на сервере остались компоненты WireGuard-выхода, хотя записан режим «" + s.modeLabel() + "»."
	case s.tunRoutingPresent() && mode != "tun_interface":
		return "на сервере остались компоненты выхода через TUN-интерфейс, хотя записан режим «" + s.modeLabel() + "»."
	}
	return ""
}

// forms are the snapshot's fields, as the screen starts editing them; never the second VPS's password.
func (s outboundSnapshot) forms() outboundProfileForms {
	return outboundProfileForms{s.t("localProxyPort"), s.t("localProxyLogin"), s.t("localProxyPassword"), s.t("externalProxyKindName"),
		s.t("externalProxyHost"), s.t("externalProxyPort"), s.t("externalProxyLogin"), s.t("externalProxyPassword"),
		s.t("wireGuardExitHost"), s.t("wireGuardExitSshPort"), s.t("wireGuardExitUser"), s.t("wireGuardExitPort"),
		s.t("wireGuardExitDns"), s.t("importedWireGuardConfig"), s.t("tunInterface")}
}

type tunCandidate struct {
	Name string `json:"name"`
	Up   bool   `json:"up"`
}

func parseTunInterfaceCandidates(output string) []tunCandidate {
	seen := map[string]bool{}
	var list []tunCandidate
	for _, line := range ktLines(output) {
		value, found := strings.CutPrefix(line, "WDTT_TUN_CANDIDATE=")
		if !found {
			continue
		}
		name, state := value, "0"
		if at := strings.Index(value, "|"); at >= 0 {
			name, state = value[:at], value[at+1:]
		}
		name, state = strings.TrimFunc(name, unicode.IsSpace), strings.TrimFunc(state, unicode.IsSpace)
		if tunInterfaceNameIssue(name) != "" || seen[name] {
			continue
		}
		seen[name] = true
		list = append(list, tunCandidate{name, state == "1"})
	}
	// Running interfaces first, then by name; at most 32.
	for i := 1; i < len(list); i++ {
		for j := i; j > 0 && (list[j].Up && !list[j-1].Up || list[j].Up == list[j-1].Up && list[j].Name < list[j-1].Name); j-- {
			list[j], list[j-1] = list[j-1], list[j]
		}
	}
	if len(list) > 32 {
		list = list[:32]
	}
	return list
}

// exitSSH is WDTT Plus's SSHClient: merged output, WDTT_PROGRESS lines as progress, a nonzero exit as "error:".
type exitSSH struct {
	p      *protocol
	client *ssh.Client
	pass   string
}

var ansiPattern = regexp.MustCompile("\x1b\\[[;\\d]*m")
var progressPattern = regexp.MustCompile(`^WDTT_PROGRESS\|(\d+\.?\d*)\|(.+)$`)

func (c *exitSSH) exec(command string, timeout time.Duration) string {
	input := ""
	// Root commands pick `sudo -S` themselves; it reads this line only when it asks.
	if c.pass != "" && strings.Contains(command, "sudo -S") {
		input = c.pass + "\n"
	}
	session, err := c.client.NewSession()
	if err != nil {
		return "error: " + err.Error()
	}
	defer session.Close()
	stdin, err := session.StdinPipe()
	if err != nil {
		return "error: " + err.Error()
	}
	writer := &exitWriter{p: c.p}
	session.Stdout, session.Stderr = writer, writer
	if err = session.Start(command + " 2>&1"); err != nil {
		return "error: " + err.Error()
	}
	go func() { _, _ = stdin.Write([]byte(input)); _ = stdin.Close() }()
	done := make(chan error, 1)
	go func() { done <- session.Wait() }()
	select {
	case err = <-done:
	case <-time.After(timeout):
		_ = session.Close()
		return "error: timeout"
	case <-c.p.ctx.Done():
		_ = session.Close()
		return "error: " + c.p.ctx.Err().Error()
	}
	result := writer.finish()
	var exit *ssh.ExitError
	switch {
	case errors.As(err, &exit):
		result += fmt.Sprintf("error: remote command exited with code %d\n", exit.ExitStatus())
	case err != nil:
		result += "error: SSH channel closed before exit status\n"
	}
	return result
}

func (c *exitSSH) upload(path string, data []byte) error {
	files, err := sftp.NewClient(c.client)
	if err != nil {
		return err
	}
	defer files.Close()
	return uploadFile(files, path, data)
}

// exitWriter turns progress lines into progress events and keeps the rest.
type exitWriter struct {
	p       *protocol
	pending string
	result  strings.Builder
}

func (w *exitWriter) Write(b []byte) (int, error) {
	w.pending += string(b)
	for {
		at := strings.IndexByte(w.pending, '\n')
		if at < 0 {
			break
		}
		w.take(strings.TrimSuffix(w.pending[:at], "\r"))
		w.pending = w.pending[at+1:]
	}
	return len(b), nil
}

func (w *exitWriter) take(line string) {
	if m := progressPattern.FindStringSubmatch(strings.TrimFunc(line, unicode.IsSpace)); m != nil {
		value, _ := strconv.ParseFloat(m[1], 64)
		w.p.emit("progress", m[2], int(min(max(value, 0), 1)*100))
		return
	}
	if strings.Contains(line, "WDTT_PROGRESS") || strings.Contains(line, "password for") {
		return
	}
	if w.result.Len() < 4*1024*1024 {
		w.result.WriteString(ansiPattern.ReplaceAllString(line, "") + "\n")
	}
}

func (w *exitWriter) finish() string {
	if w.pending != "" {
		w.take(w.pending)
		w.pending = ""
	}
	return w.result.String()
}

func hasErrorLine(output string) bool {
	return strings.HasPrefix(strings.ToLower(output), "error:") || strings.Contains(strings.ToLower(output), "\nerror:")
}

// exitTarget is the managed WDTT Plus server, always reached with the host key pinned at deploy.
type exitTarget struct {
	p *protocol
	s map[string]string
}

func (t exitTarget) pass() string {
	if t.s["user"] == "root" {
		return ""
	}
	if t.s["sudoPassword"] != "" {
		return t.s["sudoPassword"]
	}
	return t.s["sshPassword"]
}

func (t exitTarget) connect() (*exitSSH, error) {
	client, err := t.p.dial(t.s, false)
	if err != nil {
		return nil, err
	}
	return &exitSSH{t.p, client, t.pass()}, nil
}

// runRootScript uploads the script and runs it as root, as WDTT Plus runs its long scripts.
func (t exitTarget) runRootScript(script string, timeout time.Duration) (string, error) {
	c, err := t.connect()
	if err != nil {
		return "", err
	}
	defer c.client.Close()
	path := fmt.Sprintf("/tmp/wdtt-outbound-%d.sh", time.Now().UnixMilli())
	if err = c.upload(path, []byte(trimIndent(script)+"\n")); err != nil {
		return "", err
	}
	output := c.exec(exitRootCommand("chmod 700 "+path+"; bash "+path+"; code=$?; rm -f "+path+"; exit $code"), timeout)
	if _, ok := markerValue(output, "WDTT_ERROR"); ok {
		return "", errors.New(rootScriptErrorExcerpt(output))
	}
	if hasErrorLine(output) {
		return "", errors.New(takeRunes(strings.TrimFunc(output, unicode.IsSpace), 500))
	}
	return strings.TrimFunc(output, unicode.IsSpace), nil
}

// runCheckedRootScript runs a short script inline as root.
func (t exitTarget) runCheckedRootScript(script string, timeout time.Duration) (string, error) {
	c, err := t.connect()
	if err != nil {
		return "", err
	}
	defer c.client.Close()
	output := strings.TrimFunc(c.exec(exitRootCommand(script), timeout), unicode.IsSpace)
	if _, ok := markerValue(output, "WDTT_ERROR"); ok || hasErrorLine(output) {
		return "", errors.New(rootScriptErrorExcerpt(output))
	}
	return output, nil
}

// runInspection runs a read-only script inline; WDTT Plus raises only on its WDTT_ERROR marker.
func (t exitTarget) runInspection(script string, timeout time.Duration) (string, error) {
	c, err := t.connect()
	if err != nil {
		return "", err
	}
	defer c.client.Close()
	return strings.TrimFunc(c.exec(exitRootCommand(script), timeout), unicode.IsSpace), nil
}

func (t exitTarget) snapshot() (outboundSnapshot, error) {
	t.p.emit("progress", "Подключаюсь к серверу и ищу профиль выходного IP...", 25)
	output, err := t.runRootScript(outboundSnapshotScript(), 30*time.Second)
	if err != nil {
		return nil, err
	}
	t.p.emit("progress", "Настройки выходного IP прочитаны.", 100)
	return parseOutboundServerSnapshot(output), nil
}

func (t exitTarget) saved(result string, forms outboundProfileForms, message string) string {
	if _, err := t.runRootScript(outboundProfileSaveScript(forms), 30*time.Second); err != nil {
		return result + "\n" + "Режим включён, но профиль полей не сохранился на сервере: " + friendlyDeployError(err.Error(), "сохранение") + "."
	}
	return result + "\n" + message
}

func (t exitTarget) checkFreeWarp(restart bool) (string, error) {
	c, err := t.connect()
	if err != nil {
		return "", err
	}
	defer c.client.Close()
	output := strings.TrimFunc(c.exec(exitRootCommand(checkFreeWarpScript(restart)), 45*time.Second), unicode.IsSpace)
	if _, ok := markerValue(output, "WDTT_ERROR"); ok {
		return "", errors.New(rootScriptErrorExcerpt(output))
	}
	return output, nil
}

func (t exitTarget) checkWireGuardExit(mode string) (string, error) {
	t.p.emit("progress", "Подключаюсь к серверу и проверяю WireGuard-выход...", 25)
	output, err := t.runInspection(checkWireGuardExitScript(mode), 30*time.Second)
	if err != nil {
		return "", err
	}
	if marker, ok := markerValue(output, "WDTT_ERROR"); ok {
		return "", errors.New(marker)
	}
	t.p.emit("progress", "WireGuard-выход проверен.", 100)
	return output, nil
}

func (t exitTarget) checkWireGuard(mode string) (string, error) {
	s, err := t.snapshot()
	if err != nil {
		return "", err
	}
	if s.t("mode") == mode && s.b("wireGuardActive") {
		if mode == "warp_free" {
			return t.checkFreeWarp(false)
		}
		return t.checkWireGuardExit(mode)
	}
	return s.summary(), nil
}

func (t exitTarget) enableImportedWireGuard(config string) (string, error) {
	sanitized, err := sanitizeWireGuardConfigForWdttExit(config)
	if err != nil {
		return "", err
	}
	c, err := t.connect()
	if err != nil {
		return "", err
	}
	defer c.client.Close()
	if err = c.upload("/tmp/wdtt-imported-wg.conf", []byte(sanitized)); err != nil {
		return "", err
	}
	output := c.exec(exitRootCommand(shellScript(outboundShellPrelude(), exitScript(38), wireGuardPolicyScript("imported_wg", "VPN/WireGuard-файл"))), exitCommandTimeout)
	if marker, ok := markerValue(output, "WDTT_ERROR"); ok {
		return "", errors.New(marker)
	}
	return strings.TrimFunc(output, unicode.IsSpace), nil
}

// foreignServer is the second VPS: its password is used for this operation only and never kept.
type foreignServer struct {
	Host     string `json:"host"`
	SSHPort  int    `json:"sshPort"`
	User     string `json:"user"`
	Password string `json:"password"`
}

func (f foreignServer) valid() error {
	switch {
	case !isValidPublicHost(f.Host):
		return errors.New("укажите домен или IPv4 дополнительного VPS без схемы и порта")
	case f.SSHPort < 1 || f.SSHPort > 65535:
		return errors.New("SSH-порт дополнительного VPS должен быть от 1 до 65535")
	case ktIsBlank(f.User):
		return errors.New("укажите SSH-логин дополнительного VPS")
	case f.Password == "":
		return errors.New("добавьте пароль или SSH-ключ дополнительного VPS")
	}
	return nil
}

// connectForeign asks the user to trust the second VPS's host key, as the first deploy does.
func (t exitTarget) connectForeign(f foreignServer) (*exitSSH, error) {
	client, err := t.p.dial(map[string]string{"host": f.Host, "sshPort": strconv.Itoa(f.SSHPort), "user": f.User, "auth": "password", "sshPassword": f.Password}, true)
	if err != nil {
		return nil, err
	}
	return &exitSSH{t.p, client, f.Password}, nil
}

func (t exitTarget) deleteWireGuardVps(f foreignServer) (string, error) {
	if err := f.valid(); err != nil {
		return "", err
	}
	t.p.emit("progress", "Проверяю SSH-доступ к обоим VPS...", 8)
	current, err := t.connect()
	if err != nil {
		return "", err
	}
	defer current.client.Close()
	foreign, err := t.connectForeign(f)
	if err != nil {
		return "", err
	}
	defer foreign.client.Close()
	currentOutput := current.exec(exitRootCommand(deleteVpsCurrentScript()), 30*time.Second)
	if _, ok := markerValue(currentOutput, "WDTT_ERROR"); ok {
		return "", errors.New(rootScriptErrorExcerpt(currentOutput))
	}
	if v, _ := markerValue(currentOutput, "WDTT_CURRENT_WG_REMOVED"); v != "1" {
		return "", errors.New("текущий VPS не подтвердил удаление WireGuard-выхода")
	}
	foreignOutput := foreign.exec(exitRootCommand(deleteVpsForeignScript()), 30*time.Second)
	if _, ok := markerValue(foreignOutput, "WDTT_ERROR"); ok {
		return "", errors.New(rootScriptErrorExcerpt(foreignOutput))
	}
	if v, _ := markerValue(foreignOutput, "WDTT_FOREIGN_WG_REMOVED"); v != "1" {
		return "", errors.New("дополнительный VPS не подтвердил удаление WireGuard")
	}
	return "Выход через другой сервер удалён: текущий VPS использует прямой выход, созданные WDTT настройки дополнительного VPS очищены.", nil
}

// installWireGuardVps sets up the second VPS and this server as one transaction, rolling both back on failure.
func (t exitTarget) installWireGuardVps(f foreignServer, wgPort int) (result string, err error) {
	if err = f.valid(); err != nil {
		return "", err
	}
	if wgPort < 1 || wgPort > 65535 {
		return "", errors.New("порт WireGuard должен быть от 1 до 65535")
	}
	transactionID := strings.ToLower(randomToken(12))
	transaction := "/etc/wdtt-plus/wg-exit/transactions/" + transactionID
	foreignBackupDir, currentBackupDir := transaction+"/foreign", transaction+"/current"
	foreignTouched, currentTouched := false, false
	t.p.emit("progress", "Подключаюсь к текущему серверу WDTT...", 10)
	current, err := t.connect()
	if err != nil {
		return "", err
	}
	defer func() { current.client.Close() }()
	t.p.emit("progress", "Подключаюсь к другому серверу для WireGuard-выхода...", 18)
	foreign, err := t.connectForeign(f)
	if err != nil {
		return "", err
	}
	defer func() { foreign.client.Close() }()
	defer func() {
		if err == nil {
			return
		}
		incomplete := false
		if foreignTouched {
			rollback := shellScript("BACKUP_DIR="+quote(foreignBackupDir), exitScript(48))
			run := func(c *exitSSH) bool {
				v, _ := markerValue(c.exec(exitRootCommand(rollback), 45*time.Second), "WDTT_ROLLBACK_OK")
				return v == "1"
			}
			if !run(foreign) {
				foreign.client.Close()
				if again, e := t.connectForeign(f); e == nil {
					foreign = again
					incomplete = !run(foreign)
				} else {
					incomplete = true
				}
			}
		}
		if currentTouched {
			rollback := shellScript("BACKUP_DIR="+quote(currentBackupDir), outboundShellPrelude(), exitScript(49, quote(transaction)))
			run := func(c *exitSSH) bool {
				v, _ := markerValue(c.exec(exitRootCommand(rollback), 45*time.Second), "WDTT_ROLLBACK_OK")
				return v == "1"
			}
			if !run(current) {
				current.client.Close()
				if again, e := t.connect(); e == nil {
					current = again
					incomplete = !run(current) || incomplete
				} else {
					incomplete = true
				}
			}
		}
		if incomplete {
			err = errors.New(err.Error() + "\nWDTT_ERROR=outbound_rollback_incomplete")
		}
	}()
	previous := current.exec(exitRootCommand(trimIndent(exitScript(42))), 15*time.Second)
	if host, _ := markerValue(previous, "WDTT_PREVIOUS_WG_VPS_HOST"); host != "" && !strings.EqualFold(host, f.Host) {
		return "", errors.New("WDTT_ERROR=wireguard_vps_previous_server_requires_removal")
	}
	prepareKeys := shellScript(outboundShellPrelude(), exitScript(43))
	t.p.emit("progress", "Готовлю WireGuard-ключи на текущем сервере...", 28)
	currentPub, ok := markerValue(current.exec(exitRootCommand(prepareKeys), exitCommandTimeout), "WDTT_WG_PUB")
	if !ok {
		return "", errors.New("текущий сервер не отдал публичный ключ WireGuard")
	}
	t.p.emit("progress", "Готовлю WireGuard-ключи на другом сервере...", 38)
	foreignPub, ok := markerValue(foreign.exec(exitRootCommand(prepareKeys), exitCommandTimeout), "WDTT_WG_PUB")
	if !ok {
		return "", errors.New("другой сервер не отдал публичный ключ WireGuard")
	}
	foreignConfig := shellScript(exitScript(44, quote(currentPub), strconv.Itoa(wgPort), quote(foreignBackupDir)), outboundShellPrelude(), exitScript(45))
	t.p.emit("progress", "Настраиваю WireGuard на другом сервере...", 48)
	foreignTouched = true
	foreignOutput := foreign.exec(exitRootCommand(foreignConfig), exitCommandTimeout)
	if _, ok := markerValue(foreignOutput, "WDTT_ERROR"); ok {
		return "", errors.New(rootScriptErrorExcerpt(foreignOutput))
	}
	if v, _ := markerValue(foreignOutput, "WDTT_FOREIGN_READY"); v != "1" {
		return "", errors.New("другой сервер не подтвердил запуск WireGuard")
	}
	currentConfig := shellScript(exitScript(46, quote(foreignPub), quote(f.Host), strconv.Itoa(wgPort), quote(currentBackupDir)), outboundShellPrelude(),
		exitScript(47), wireGuardPolicyScript("wireguard_vps", "другой сервер "+f.Host+":"+strconv.Itoa(wgPort)))
	t.p.emit("progress", "Применяю WireGuard-выход на текущем сервере...", 72)
	currentTouched = true
	output := current.exec(exitRootCommand(currentConfig), exitCommandTimeout)
	for _, line := range ktLines(output) {
		if strings.HasPrefix(line, "error:") {
			return "", errors.New(rootScriptErrorExcerpt(output))
		}
	}
	if strings.Contains(output, "WDTT_ERROR=") {
		return "", errors.New(rootScriptErrorExcerpt(output))
	}
	current.exec(exitRootCommand("rm -rf "+quote(transaction)), 15*time.Second)
	foreign.exec(exitRootCommand("rm -rf "+quote(transaction)), 15*time.Second)
	currentTouched, foreignTouched = false, false
	t.p.emit("progress", "WireGuard-выход через другой сервер включён.", 100)
	if text := strings.TrimFunc(output, unicode.IsSpace); text != "" {
		return text, nil
	}
	return "Выход через WireGuard включён для WDTT-пользователей.", nil
}

// exitRequest is one action of the screen; the fields an action does not use stay empty.
type exitRequest struct {
	Action   string        `json:"action"`
	Label    string        `json:"label"`
	Port     int           `json:"port"`
	Login    string        `json:"login"`
	Password string        `json:"password"`
	Kind     string        `json:"kind"`
	Host     string        `json:"host"`
	Name     string        `json:"name"`
	MTU      int           `json:"mtu"`
	Config   string        `json:"config"`
	WGPort   int           `json:"wgPort"`
	Foreign  foreignServer `json:"foreign"`
}

// preflightActions switch the route: they stop on a route conflict left on the server.
var preflightActions = map[string]bool{"external-enable": true, "tun-enable": true, "vps-install": true, "warp-install": true, "wg-enable": true}

func (p *protocol) wdttPlusExit(s map[string]string, raw string) (any, error) {
	var r exitRequest
	if json.Unmarshal([]byte(raw), &r) != nil || r.Action == "" {
		return nil, errors.New("Некорректный запрос к серверу")
	}
	p.secrets = append(p.secrets, r.Password, r.Foreign.Password)
	if r.Action == "wg-validate" {
		if err := validateWireGuardConfigText(r.Config); err != nil {
			return map[string]any{"text": "Ошибка VPN/WireGuard-файла: " + err.Error(), "failed": true}, nil
		}
		return map[string]any{"text": "Файл подходит."}, nil
	}
	t := exitTarget{p, s}
	if r.Action == "tun-candidates" {
		output, err := t.runInspection(tunInterfaceCandidatesScript(), 30*time.Second)
		if err != nil {
			return nil, err
		}
		return map[string]any{"candidates": parseTunInterfaceCandidates(output)}, nil
	}
	var snapshot outboundSnapshot
	if preflightActions[r.Action] || r.Action == "load" {
		var err error
		if snapshot, err = t.snapshot(); err != nil {
			return nil, errors.New(friendlyDeployError(err.Error(), "выходной IP"))
		}
		if r.Action == "load" {
			return map[string]any{"text": snapshot.summary(), "snapshot": snapshot}, nil
		}
		if conflict := snapshot.routeConflictMessage(); conflict != "" {
			return map[string]any{"text": "Установка остановлена. " + conflict, "snapshot": snapshot}, nil
		}
	}
	text, err := t.action(r, snapshot)
	if err != nil {
		return nil, errors.New(friendlyDeployError(err.Error(), "выходной IP"))
	}
	if ktIsBlank(text) {
		text = r.Label + ": готово"
	}
	// Every action ends by re-reading the server and warning about anything left half set up.
	after, afterErr := t.snapshot()
	result := map[string]any{"text": text}
	if afterErr != nil {
		result["text"] = text + "\nПроверьте сервер: Действие завершено, но обновить состояние сервера не удалось."
	} else {
		result["snapshot"] = after
		if warning := after.warning(); warning != "" {
			result["text"] = text + "\nПроверьте сервер: " + warning
		}
	}
	return result, nil
}

func (t exitTarget) action(r exitRequest, snapshot outboundSnapshot) (string, error) {
	forms := func() outboundProfileForms {
		if snapshot == nil {
			if s, err := t.snapshot(); err == nil {
				snapshot = s
			}
		}
		if snapshot == nil {
			return outboundProfileForms{}
		}
		return snapshot.forms()
	}
	switch r.Action {
	case "status":
		t.p.emit("progress", "Подключаюсь к серверу и читаю текущий режим выхода...", 25)
		output, err := t.runInspection(outboundStatusScript(), 30*time.Second)
		t.p.emit("progress", "Статус выхода получен.", 100)
		return output, err
	case "diagnostics":
		t.p.emit("progress", "Собираю маршруты и правила перенаправления...", 75)
		output, err := t.runInspection(shellScript(outboundStatusScript(), exitScript(13)), 30*time.Second)
		t.p.emit("progress", "Диагностика собрана.", 100)
		return output, err
	case "direct":
		return t.runCheckedRootScript(disableOutboundExitScript(), 30*time.Second)
	case "local-install":
		script, err := buildLocalProxyInstallScript(r.Port, r.Login, r.Password)
		if err != nil {
			return "", err
		}
		f := forms()
		f.LocalProxyPort, f.LocalProxyLogin, f.LocalProxyPassword = strconv.Itoa(r.Port), r.Login, r.Password
		output, err := t.runRootScript(script, exitCommandTimeout)
		if err != nil {
			return "", err
		}
		return t.saved(output, f, "Поля прокси сохранены на сервере для восстановления."), nil
	case "local-check":
		script, err := checkLocalProxyScript(r.Port, r.Login, r.Password)
		if err != nil {
			return "", err
		}
		return t.runRootScript(script, 30*time.Second)
	case "local-stop":
		return t.runCheckedRootScript(stopLocalProxyScript(), 20*time.Second)
	case "local-remove":
		return t.runCheckedRootScript(removeLocalProxyScript(), 30*time.Second)
	case "external-check", "external-enable":
		kind, ok := proxyKindByName(r.Kind)
		if !ok {
			return "", errors.New("Выберите тип прокси")
		}
		if r.Action == "external-check" {
			script, err := checkExternalProxyScript(kind, r.Host, r.Port, r.Login, r.Password)
			if err != nil {
				return "", err
			}
			return t.runRootScript(script, 30*time.Second)
		}
		script, err := enableExternalProxyScript(kind, r.Host, r.Port, r.Login, r.Password)
		if err != nil {
			return "", err
		}
		f := forms()
		f.ExternalProxyKindName, f.ExternalProxyHost, f.ExternalProxyPort, f.ExternalProxyLogin, f.ExternalProxyPassword = kind.name, r.Host, strconv.Itoa(r.Port), r.Login, r.Password
		output, err := t.runRootScript(script, exitCommandTimeout)
		if err != nil {
			return "", err
		}
		return t.saved(output, f, "Поля внешнего прокси сохранены на сервере для восстановления."), nil
	case "external-delete":
		return t.runCheckedRootScript(deleteExternalProxyScript(), 30*time.Second)
	case "tun-enable":
		script, err := buildTunInterfaceExitScript(r.Name)
		if err != nil {
			return "", err
		}
		f := forms()
		f.TunInterface = strings.TrimFunc(r.Name, unicode.IsSpace)
		output, err := t.runCheckedRootScript(script, 60*time.Second)
		if err != nil {
			return "", err
		}
		return t.saved(output, f, "Имя TUN-интерфейса сохранено на сервере для восстановления."), nil
	case "tun-check":
		s, err := t.snapshot()
		if err != nil {
			return "", err
		}
		if s.t("mode") == "tun_interface" && s.tunHealthy() {
			script, err := checkTunInterfaceExitScript(s.t("tunInterface"))
			if err != nil {
				return "", err
			}
			return t.runCheckedRootScript(script, 30*time.Second)
		}
		return s.summary(), nil
	case "tun-delete":
		return t.runCheckedRootScript(deleteTunInterfaceExitScript(), 30*time.Second)
	case "vps-install":
		f := forms()
		f.WireGuardExitHost, f.WireGuardExitSSHPort, f.WireGuardExitUser, f.WireGuardExitPort = r.Foreign.Host, strconv.Itoa(r.Foreign.SSHPort), r.Foreign.User, strconv.Itoa(r.WGPort)
		output, err := t.installWireGuardVps(r.Foreign, r.WGPort)
		if err != nil {
			return "", err
		}
		return t.saved(output, f, "Поля выхода через другой сервер сохранены на сервере для восстановления."), nil
	case "vps-check":
		return t.checkWireGuard("wireguard_vps")
	case "vps-delete":
		return t.deleteWireGuardVps(r.Foreign)
	case "warp-install":
		script, err := buildFreeWarpInstallScript(r.MTU)
		if err != nil {
			return "", err
		}
		return t.runRootScript(script, exitCommandTimeout)
	case "warp-check":
		return t.checkWireGuard("warp_free")
	case "warp-restart":
		return t.checkFreeWarp(true)
	case "warp-update":
		return t.runRootScript(shellScript(outboundShellPrelude(), wgcfToolManagementScript(), exitScript(31)), 8*time.Minute)
	case "warp-reset", "warp-delete":
		c, err := t.connect()
		if err != nil {
			return "", err
		}
		defer c.client.Close()
		n := 36
		if r.Action == "warp-delete" {
			n = 37
		}
		output := strings.TrimFunc(c.exec(exitRootCommand(shellScript(outboundShellPrelude(), exitScript(n))), 60*time.Second), unicode.IsSpace)
		if _, ok := markerValue(output, "WDTT_ERROR"); ok {
			return "", errors.New(rootScriptErrorExcerpt(output))
		}
		return output, nil
	case "wg-enable":
		f := forms()
		f.ImportedWireGuardConfig = r.Config
		output, err := t.enableImportedWireGuard(r.Config)
		if err != nil {
			return "", err
		}
		return t.saved(output, f, "VPN/WireGuard-файл сохранён на сервере для восстановления."), nil
	case "wg-check":
		return t.checkWireGuard("imported_wg")
	case "wg-delete":
		return t.runCheckedRootScript(deleteImportedWireGuardScript(), 30*time.Second)
	}
	return "", errors.New("Неизвестное действие")
}
